package main
import("crypto/sha256";"encoding/binary";"fmt";"time";"github.com/yangl1996/riblt")
func source256(v uint64)largeItem{var b[8]byte;binary.LittleEndian.PutUint64(b[:],v);return largeItem(sha256.Sum256(b[:]))}
func representative(){key0=123;key1=456;report:=map[string]any{"codec":"floor expectation + ZigZag unsigned LEB128; paper-derived, not official wire code","hash":"full SipHash64(123,456)","symbol_bits":256};counts:=[]map[string]any{}
 for trial:=0;trial<10;trial++{var e riblt.Encoder[largeItem];for j:=0;j<1000000;j++{e.AddSymbol(source256(uint64(trial)*2000000+uint64(j)))};total:=0;negative,zero,positive:=0,0,0;for i:=0;i<10000;i++{c:=e.ProduceNextCodedSymbol();b:=encodeCount(nil,c.Count,1000000,i);x,_,err:=decodeCount(b,1000000,i);if x!=c.Count||err!=nil{panic("representative count roundtrip")};total+=len(b);delta:=c.Count-expectation(1000000,i);if delta<0{negative++}else if delta>0{positive++}else{zero++}};counts=append(counts,map[string]any{"trial":trial,"set_size":1000000,"coded_symbols":10000,"count_bytes":total,"mean_count_bytes":float64(total)/10000,"negative":negative,"zero":zero,"positive":positive})};report["count_trials"]=counts
 ratios:=[]map[string]any{};for trial:=0;trial<100;trial++{var enc riblt.Encoder[largeItem];var dec riblt.Decoder[largeItem];d:=100000;start:=uint64(trial)*200000;for j:=0;j<d;j++{v:=source256(start+uint64(j));if j%2==0{enc.AddSymbol(v)}else{dec.AddSymbol(v)}};done:=false;symbols:=0;for symbols<10000000{symbols++;dec.AddCodedSymbol(enc.ProduceNextCodedSymbol());dec.TryDecode();if dec.Decoded(){done=true;break}};if !done||len(dec.Local())!=d/2||len(dec.Remote())!=d/2{panic("ratio representative failed")};seen:=map[largeItem]bool{};for _,x:=range dec.Remote(){seen[x.Symbol]=true};for j:=0;j<d;j+=2{if !seen[source256(start+uint64(j))]{panic("truth")}};seen=map[largeItem]bool{};for _,x:=range dec.Local(){seen[x.Symbol]=true};for j:=1;j<d;j+=2{if !seen[source256(start+uint64(j))]{panic("truth")}};ratios=append(ratios,map[string]any{"trial":trial,"d":d,"symbols":symbols,"symbols_per_d":float64(symbols)/float64(d),"truth_verified":true})};report["ratio_trials"]=ratios
 // A direct full-set §7.1-style exercise, extended to d=100000.
 full:=[]map[string]any{};for trial:=0;trial<3;trial++{var e riblt.Encoder[largeItem];var b riblt.Encoder[largeItem];var dec riblt.Decoder[largeItem];n,d:=1000000,100000;offset:=uint64(trial)*3000000;for j:=0;j<n;j++{e.AddSymbol(source256(offset+uint64(j)));b.AddSymbol(source256(offset+uint64(j+d/2)))};m,countBytes:=0,0;wall:=time.Now();for m<10000000{c:=e.ProduceNextCodedSymbol();raw:=encodeCount(nil,c.Count,uint64(n),m);restored,_,err:=decodeCount(raw,uint64(n),m);if err!=nil||restored!=c.Count{panic("full count")};countBytes+=len(raw);other:=b.ProduceNextCodedSymbol();c.Symbol=c.Symbol.XOR(other.Symbol);c.Hash^=other.Hash;c.Count=restored-other.Count;dec.AddCodedSymbol(c);dec.TryDecode();m++;if dec.Decoded(){break}};seen:=map[largeItem]bool{};for _,x:=range dec.Remote(){seen[x.Symbol]=true};if len(seen)!=d/2{panic("full remote")};for j:=0;j<d/2;j++{if !seen[source256(offset+uint64(j))]{panic("full truth")}};seen=map[largeItem]bool{};for _,x:=range dec.Local(){seen[x.Symbol]=true};if len(seen)!=d/2{panic("full local")};for j:=n;j<n+d/2;j++{if !seen[source256(offset+uint64(j))]{panic("full truth local")}};full=append(full,map[string]any{"trial":trial,"N":n,"d":d,"symbol_bits":256,"symbols":m,"symbols_per_d":float64(m)/float64(d),"count_mean_bytes":float64(countBytes)/float64(m),"truth_verified":true,"wall_s":time.Since(wall).Seconds()})};report["full_set_trials"]=full;report["finished"]=fmt.Sprint(time.Now().UTC());printJSON(report)}
